    } else if (value is NativeFailure) {
      buffer.putUint8(134);
      writeValue(buffer, value.index);
    } else if (value is InstallerPhase) {
      buffer.putUint8(135);
      writeValue(buffer, value.index);
    } else if (value is ReconcileResult) {
      buffer.putUint8(136);
      writeValue(buffer, value.index);
    } else if (value is PlayAvailability) {
      buffer.putUint8(137);
      writeValue(buffer, value.index);
    } else if (value is PlayFailure) {
      buffer.putUint8(138);
      writeValue(buffer, value.index);
    } else if (value is PlayFlowResult) {
      buffer.putUint8(139);
      writeValue(buffer, value.index);
    } else if (value is PlayInstallStatus) {
      buffer.putUint8(140);
      writeValue(buffer, value.index);
    } else if (value is ComponentIdentityMessage) {
      buffer.putUint8(141);
      writeValue(buffer, value.encode());
    } else if (value is InstalledBuildInfo) {
      buffer.putUint8(142);
      writeValue(buffer, value.encode());
    } else if (value is UpdateDirs) {
      buffer.putUint8(143);
      writeValue(buffer, value.encode());
    } else if (value is ExpectedArtifact) {
      buffer.putUint8(144);
      writeValue(buffer, value.encode());
    } else if (value is ApkVerificationResult) {
      buffer.putUint8(145);
      writeValue(buffer, value.encode());
    } else if (value is InstallCommitResult) {
      buffer.putUint8(146);
      writeValue(buffer, value.encode());
    } else if (value is InstallerReconciliation) {
      buffer.putUint8(147);
      writeValue(buffer, value.encode());
    } else if (value is PlayUpdateInfo) {
      buffer.putUint8(148);
      writeValue(buffer, value.encode());
    } else if (value is InstallerStatusEvent) {
      buffer.putUint8(149);
      writeValue(buffer, value.encode());
    } else if (value is PlayInstallStateEvent) {
      buffer.putUint8(150);
      writeValue(buffer, value.encode());
    } else {
      super.writeValue(buffer, value);
    }
  }

  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    switch (type) {
      case 129:
        final value = readValue(buffer) as int?;
        return value == null ? null : BuildDistribution.values[value];
      case 130:
        final value = readValue(buffer) as int?;
        return value == null ? null : BuildTrack.values[value];
      case 131:
        final value = readValue(buffer) as int?;
        return value == null ? null : BuildRenderer.values[value];
      case 132:
        final value = readValue(buffer) as int?;
        return value == null ? null : BuildComponent.values[value];
      case 133:
