      case 134:
        final value = readValue(buffer) as int?;
        return value == null ? null : NativeFailure.values[value];
      case 135:
        final value = readValue(buffer) as int?;
        return value == null ? null : InstallerPhase.values[value];
      case 136:
        final value = readValue(buffer) as int?;
        return value == null ? null : ReconcileResult.values[value];
      case 137:
        final value = readValue(buffer) as int?;
        return value == null ? null : PlayAvailability.values[value];
      case 138:
        final value = readValue(buffer) as int?;
        return value == null ? null : PlayFailure.values[value];
      case 139:
        final value = readValue(buffer) as int?;
        return value == null ? null : PlayFlowResult.values[value];
      case 140:
        final value = readValue(buffer) as int?;
        return value == null ? null : PlayInstallStatus.values[value];
      case 141:
        return ComponentIdentityMessage.decode(readValue(buffer)!);
      case 142:
        return InstalledBuildInfo.decode(readValue(buffer)!);
      case 143:
        return UpdateDirs.decode(readValue(buffer)!);
      case 144:
        return ExpectedArtifact.decode(readValue(buffer)!);
      case 145:
        return ApkVerificationResult.decode(readValue(buffer)!);
      case 146:
        return InstallCommitResult.decode(readValue(buffer)!);
      case 147:
