/// Returns a broadcast [Stream] of events from the `streamInstallerEvents` event channel.
///
/// Each call to this method creates a new [EventChannel], so it should
/// not be called multiple times for the same `instanceName`. To deliver
/// events to multiple listeners, call this method once and listen to the
/// returned broadcast stream multiple times instead.
Stream<InstallerStatusEvent> streamInstallerEvents({String instanceName = ''}) {
  if (instanceName.isNotEmpty) {
    instanceName = '.$instanceName';
  }
  final EventChannel streamInstallerEventsChannel = EventChannel(
    'dev.flutter.pigeon.weblibre.AppUpdateEventsApi.streamInstallerEvents$instanceName',
    pigeonMethodCodec,
  );
  return streamInstallerEventsChannel.receiveBroadcastStream().map((
    dynamic event,
  ) {
    return event as InstallerStatusEvent;
  });
}

